<template><section class="b-panel"><h2>成长规则</h2><p class="b-muted">新版本奖励只用于此后创建的赛事。历史积分保留原规则依据，段位展示按当前版本计算。</p><el-select v-model="sportId" @change="load"><el-option v-for="sport in sports" :key="sport.id" :label="sport.name" :value="sport.id"/></el-select><el-alert v-if="error" :title="error" type="warning" :closable="false"/><template v-if="rules"><el-form label-position="top"><div class="rule-points"><el-form-item label="真实报到积分"><el-input-number v-model="rules.checkinPoints" :min="0" :max="10000"/></el-form-item><el-form-item label="个人有效完赛积分"><el-input-number v-model="rules.finishPoints" :min="0" :max="10000"/></el-form-item><el-form-item label="长期小队完赛积分"><el-input-number v-model="rules.teamFinishPoints" :min="0" :max="10000"/></el-form-item></div><el-table :data="rankRows"><el-table-column label="段位名称"><template #default="{row}"><el-input v-model="rules.rankNames[row.index]" maxlength="20"/></template></el-table-column><el-table-column label="成长分门槛"><template #default="{row}"><el-input-number v-model="rules.thresholds[row.index]" :min="0" :max="10000000" :disabled="row.index===0"/></template></el-table-column></el-table><h3>称号获得次数</h3><div class="rule-points"><el-form-item v-for="(name,code) in titleLabels" :key="code" :label="name"><el-input-number v-if="code.startsWith('team_')" v-model="rules.teamTitles[code]" :min="1" :max="10000"/><el-input-number v-else v-model="rules.personalTitles[code]" :min="1" :max="10000"/></el-form-item></div><el-button type="primary" :loading="busy" @click="save">核对并发布第 {{revision+1}} 版</el-button></el-form></template><el-button v-else-if="sportId" @click="initial">为该运动准备初始规则</el-button></section></template>
<script setup lang="ts">
import request from '@/utils/request';import {performAction,titleLabels} from '@/api/sports/phase1';
interface Rules {checkinPoints:number;finishPoints:number;teamFinishPoints:number;thresholds:number[];rankNames:string[];personalTitles:Record<string,number>;teamTitles:Record<string,number>}
const sports=ref<{id:string;name:string;code:string}[]>([]),sportId=ref(''),rules=ref<Rules>(),revision=ref(0),busy=ref(false),error=ref('');const rankRows=computed(()=>Array.from({length:rules.value?.rankNames.length||0},(_,index)=>({index})));
function initial(){rules.value={checkinPoints:10,finishPoints:30,teamFinishPoints:40,thresholds:[0,40,120,400,1000,2400,4800,9600,19200],rankNames:['新星','青铜','白银','黄金','铂金','钻石','星耀','王者','传奇'],personalTitles:{first_checkin:1,first_finish:1,regular:3},teamTitles:{team_first:1,team_partners:3,team_veterans:10}};}
async function load(){error.value='';rules.value=undefined;try{const response=await request<{revision:number;rules:string}[]>({url:'/sports/platform/actions/growth.policy.save/preview',method:'post',data:{sportId:sportId.value,rulesJson:'{}',expectedVersion:0}});const row=response.data[0];revision.value=row?.revision||0;if(row)rules.value=JSON.parse(row.rules);}catch{error.value='规则能力尚未开放，或当前账号没有管理权限。';}}
async function save(){if(!rules.value)return;busy.value=true;try{await performAction('growth.policy.save',{sportId:sportId.value,rulesJson:JSON.stringify(rules.value),expectedVersion:revision.value},'确认发布这一版门槛、奖励和称号次数？历史赛事事实保留原版依据。');await load();}finally{busy.value=false;}}
onMounted(async()=>{sports.value=(await request({url:'/sports/types',headers:{isToken:false}})).data.sports;sportId.value=sports.value.find(s=>s.code==='badminton')?.id||sports.value[0]?.id||'';if(sportId.value)await load();});
</script>
<style scoped>.rule-points{display:flex;gap:24px;flex-wrap:wrap;margin:24px 0}</style>
